'use strict';const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');const html=fs.readFileSync(__dirname+'/cargo.html','utf8'),core=html.match(/<script id="cargo-core">([\s\S]*?)<\/script>/)[1],context={};vm.createContext(context);vm.runInContext(core,context);const E=context.OddCargo;let tests=0;function test(name,fn){fn();console.log('PASS',++tests,name);}const frame=s=>E.step(s,1/60);
function plantRoute(s){E.input(s,'down',s.cargo.x,s.cargo.y);for(const target of [{x:330,y:155},{x:550,y:350},{x:800,y:165}]){E.input(s,'move',target.x,target.y);for(let i=0;i<220&&s.phase==='playing'&&Math.hypot(s.cargo.x-target.x,s.cargo.y-target.y)>5;i++)frame(s);for(let i=0;i<45&&s.phase==='playing';i++)frame(s);}}
function shyRoute(s){for(let i=0;i<1800&&s.phase==='playing';i++){const gate=s.cargo.x<376?0:1,x=gate===0?345:610,phase=(s.time+(gate===1?2:0))%4,waiting=s.cargo.x<x-32&&x-s.cargo.x<80&&(!E.gateOpen(s,gate)||1.6-phase<1.05);if(waiting)E.input(s,'down');else E.input(s,'release');frame(s);}}
function magnetRoute(s){E.input(s,'down',s.magnet.x,s.magnet.y);for(const target of [{x:195,y:445},{x:405,y:445},{x:440,y:150},{x:650,y:150},{x:800,y:300}]){for(let i=0;i<600&&s.phase==='playing';i++){const dx=target.x-s.cargo.x,dy=target.y-s.cargo.y,d=Math.hypot(dx,dy);if(d<8)break;const reach=Math.min(115,d);E.input(s,'move',s.cargo.x+dx/d*reach,s.cargo.y+dy/d*reach);frame(s);}}}
test('plant reaches recipient through light pools',()=>{const s=E.create(0);E.begin(s);plantRoute(s);assert.equal(s.phase,'won');assert(s.health>0);});
test('plant waiting in shadow fails visibly',()=>{const s=E.create(0);E.begin(s);s.cargo.x=420;s.cargo.y=480;for(let i=0;i<200&&s.phase==='playing';i++)frame(s);assert.equal(s.phase,'lost');assert.equal(s.reason,'dark');});
test('shy parcel needs observation timing and can reach recipient',()=>{const s=E.create(1);E.begin(s);shyRoute(s);assert.equal(s.phase,'won');const unattended=E.create(1);E.begin(unattended);for(let i=0;i<600&&unattended.phase==='playing';i++)frame(unattended);assert.equal(unattended.phase,'lost');});
test('watching freezes parcel while gates continue cycling',()=>{const s=E.create(1);E.begin(s);E.input(s,'down');for(let i=0;i<120;i++)frame(s);assert.equal(s.cargo.x,100);assert(s.time>1.9);E.input(s,'release');frame(s);assert(s.cargo.x>100);});
test('magnet route around both partitions reaches recipient',()=>{const s=E.create(2);E.begin(s);magnetRoute(s);assert.equal(s.phase,'won');});
test('magnet has finite range and walls cannot be dragged through',()=>{const s=E.create(2);E.begin(s);E.input(s,'down',850,50);for(let i=0;i<180;i++)frame(s);assert.equal(s.cargo.x,100);assert.equal(s.cargo.y,300);s.cargo.x=255;s.cargo.y=300;E.input(s,'move',400,300);for(let i=0;i<240;i++)frame(s);assert(s.cargo.x<=261.01);assert(s.blocked);});
test('ready state does not tick; retry factory clears time, watch, drag and outcomes',()=>{for(const level of [0,1,2,3,4,5,6]){let s=E.create(level);E.step(s,10);assert.equal(s.time,0);E.begin(s);E.input(s,'down',100,300);frame(s);s=E.create(level);assert.equal(s.time,0);assert.equal(s.phase,'ready');assert.equal(s.watched,false);assert.equal(s.drag,false);assert.equal(s.delivered,0);}});
test('drag pointer and cargo stay in world bounds, invalid input cannot corrupt state',()=>{for(const level of [0,2]){const s=E.create(level);E.begin(s);E.input(s,'down',s.cargo.x,s.cargo.y);E.input(s,'move',50000,-50000);for(let i=0;i<400;i++)frame(s);assert(s.cargo.x>=19&&s.cargo.x<=881&&s.cargo.y>=19&&s.cargo.y<=501);assert(s.pointer.x<=878&&s.pointer.y>=22);E.input(s,'move',NaN,Infinity);assert(Number.isFinite(s.cargo.x));}});
test('standalone page has bilingual gallery link and no external dependency',()=>{assert(html.includes('href="index.html"'));assert(html.includes('Back to gallery'));assert(!/<script[^>]+src=/.test(html));assert(!/https?:\/\//.test(html));});
module.exports={E,plantRoute,shyRoute,magnetRoute};
function uiHarness(real=false){const ids=[...html.matchAll(/id="([^"]+)"/g)].map(m=>m[1]),nodes={};for(const id of ids)nodes[id]={textContent:'',attributes:{},events:{},dataset:{},classList:{values:new Set(),toggle(key,value){if(value)this.values.add(key);else this.values.delete(key);}},setAttribute(k,v){this.attributes[k]=v;},addEventListener(k,f){this.events[k]=f;},setPointerCapture(){}};const buttons=Array.from({length:E.levels},(_,i)=>i).map(i=>({...nodes.number,dataset:{level:String(i)},attributes:{},setAttribute(k,v){this.attributes[k]=v;}}));let imageCanvas;const fakeCtx=new Proxy({createRadialGradient:()=>({addColorStop(){}})},{get:(o,k)=>k in o?o[k]:()=>{},set:(o,k,v)=>(o[k]=v,true)});let ctx=fakeCtx;if(real){const {createCanvas,GlobalFonts}=require('@napi-rs/canvas');GlobalFonts.registerFromPath('/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc','sans-serif');imageCanvas=createCanvas(900,520);ctx=imageCanvas.getContext('2d');Object.defineProperty(nodes.game,'width',{get:()=>imageCanvas.width,set:x=>imageCanvas.width=x});Object.defineProperty(nodes.game,'height',{get:()=>imageCanvas.height,set:x=>imageCanvas.height=x});}nodes.game.getContext=()=>ctx;nodes.game.getBoundingClientRect=()=>({left:0,top:0,width:900,height:520});const events={},c={OddCargo:E,console,requestAnimationFrame(){},document:{hidden:false,documentElement:{},getElementById:id=>nodes[id],querySelectorAll:()=>buttons,addEventListener(k,v){events[k]=v;}},addEventListener(k,v){events[k]=v;},devicePixelRatio:1};c.window=c;vm.createContext(c);let script=html.match(/<script id="cargo-ui">([\s\S]*?)<\/script>/)[1];script=script.replace('})();','globalThis.UI={read:()=>s,choose,frame,draw,renderUI};})();');vm.runInContext(script,c);return{ui:c.UI,nodes,events,buttons,imageCanvas,context:c};}
test('language switch preserves ongoing cargo position, timer and current level',()=>{const h=uiHarness();h.ui.choose(1);h.nodes.start.onclick();h.ui.frame(0);h.ui.frame(50);const before=JSON.stringify(h.ui.read());h.nodes.lang.onclick();assert.equal(JSON.stringify(h.ui.read()),before);assert.equal(h.nodes.title.textContent,'Odd Cargo');assert.equal(h.nodes.back.textContent,'Back to gallery');h.nodes.lang.onclick();assert.equal(JSON.stringify(h.ui.read()),before);});
test('actual pointer handlers drag plant, release capture, and retry resets all timing',()=>{const h=uiHarness();h.nodes.start.onclick();h.nodes.game.events.pointerdown({clientX:100,clientY:350,pointerId:1,preventDefault(){}});h.nodes.game.events.pointermove({clientX:200,clientY:250});h.ui.frame(0);h.ui.frame(50);assert(h.ui.read().cargo.x>100);h.nodes.game.events.pointerup();assert(!h.ui.read().drag);h.nodes.retry.onclick();assert.equal(h.ui.read().time,0);assert.equal(h.ui.read().phase,'ready');assert.equal(h.ui.read().cargo.x,100);});
test('watch button and blur release do not leave shy parcel permanently held',()=>{const h=uiHarness();h.buttons[1].onclick();h.nodes.start.onclick();h.nodes.watch.events.pointerdown({pointerId:2,preventDefault(){}});assert(h.ui.read().watched);h.events.blur();assert(!h.ui.read().watched);});
if(process.argv.includes('--render')){const h=uiHarness(true);for(let i=0;i<E.levels;i++){h.ui.choose(i);h.nodes.start.onclick();h.ui.draw();fs.writeFileSync(__dirname+`/cargo-level-${i+1}.png`,h.imageCanvas.toBuffer('image/png'));}console.log('Rendered actual Canvas scenes; not browser layout verification.');}
function mirrorRoute(s){E.input(s,'down',s.cargo.x,s.cargo.y);for(const p of [{x:330,y:410},{x:330,y:125},{x:140,y:125}]){E.input(s,'move',p.x,p.y);for(let i=0;i<300&&s.phase==='playing'&&Math.hypot(s.cargo.x-p.x,s.cargo.y-p.y)>3;i++)frame(s);}}
function balloonRoute(s){for(let i=0;i<1100&&s.phase==='playing';i++){const target=s.cargo.x<370?330:s.cargo.x<650?210:230,desired=Math.max(-100,Math.min(100,(target-s.cargo.y)*3));if(s.cargo.vy>desired)E.input(s,'down');else E.input(s,'release');frame(s);}}
test('mirror twins reach both desks through coordinated path',()=>{const s=E.create(3);E.begin(s);mirrorRoute(s);assert.equal(s.phase,'won');assert(Math.abs(s.cargo.x+s.twin.x-900)<1e-8);assert.equal(s.cargo.y,s.twin.y);assert.equal(s.delivered,1);});
test('mirror twin collision blocks both, scanner causes explicit failure',()=>{const s=E.create(3);E.begin(s);E.input(s,'down',140,410);E.input(s,'move',140,120);for(let i=0;i<180;i++)frame(s);assert(s.blocked);assert(s.cargo.y>=307-1e-4);E.input(s,'move',450,410);for(let i=0;i<240&&s.phase==='playing';i++)frame(s);assert.equal(s.phase,'lost');assert.equal(s.reason,'scanner');});
test('either twin can be dragged, but movement stays mirrored and bounded',()=>{const s=E.create(3);E.begin(s);E.input(s,'down',760,410);E.input(s,'move',700,440);for(let i=0;i<45;i++)frame(s);assert(s.cargo.x>140&&s.twin.x<760);E.input(s,'move',9999,9999);for(let i=0;i<120;i++)frame(s);assert(s.twin.x<=881&&s.twin.y<=501);assert.equal(s.cargo.x+s.twin.x,900);});
test('balloon delivery is reachable by timing inflation through two windows',()=>{const s=E.create(4);E.begin(s);balloonRoute(s);assert.equal(s.phase,'won',JSON.stringify(s));assert(s.time>8);});
test('balloon cannot coast unattended or inflate forever without collision',()=>{for(const hold of [false,true]){const s=E.create(4);E.begin(s);if(hold)E.input(s,'down');for(let i=0;i<700&&s.phase==='playing';i++)frame(s);assert.equal(s.phase,'lost');assert.equal(s.reason,'balloon-hit');}});
test('new levels actual input, language switch and retry preserve/reset appropriate state',()=>{for(const level of [3,4]){const h=uiHarness();h.buttons[level].onclick();h.nodes.start.onclick();if(level===3){h.nodes.game.events.pointerdown({clientX:760,clientY:410,pointerId:8,preventDefault(){}});h.nodes.game.events.pointermove({clientX:700,clientY:440});}else h.nodes.watch.events.pointerdown({pointerId:8,preventDefault(){}});h.ui.frame(0);h.ui.frame(50);const before=JSON.stringify(h.ui.read());h.nodes.lang.onclick();assert.equal(JSON.stringify(h.ui.read()),before);assert(h.nodes.instruction.textContent.includes(level===3?'twin':'accelerate'));h.events.blur();assert(!h.ui.read().drag&&!h.ui.read().watched);h.nodes.retry.onclick();assert.equal(h.ui.read().time,0);assert.equal(h.ui.read().phase,'ready');assert.equal(h.ui.read().level,level);}});
test('UI-only optional progress reports each victory once and never reports loss',()=>{const h=uiHarness(),calls=[];h.context.TrialProgress={complete:(...args)=>calls.push(args)};h.ui.choose(3);h.nodes.start.onclick();mirrorRoute(h.ui.read());h.ui.frame(0);h.ui.frame(20);assert.equal(calls.length,1);assert.equal(calls[0][0],'cargo');assert.equal(calls[0][1],3);assert(calls[0][2].seconds>0);h.nodes.retry.onclick();h.nodes.start.onclick();mirrorRoute(h.ui.read());h.ui.frame(40);assert.equal(calls.length,2);h.ui.choose(4);h.nodes.start.onclick();for(let i=0;i<700&&h.ui.read().phase==='playing';i++)frame(h.ui.read());h.ui.frame(100);assert.equal(calls.length,2);});

function nightRoute(s,followLights=true){let minimum=100;for(let i=0;i<1200&&s.phase==='playing';i++){const target=followLights?(s.cargo.x<300?190:s.cargo.x<540?350:230):230,desired=Math.max(-100,Math.min(100,(target-s.cargo.y)*3));E.input(s,s.cargo.vy>desired?'down':'release');frame(s);minimum=Math.min(minimum,s.health);}return minimum;}
test('night greenhouse combines height control and genuine light replenishment',()=>{const s=E.create(5);E.begin(s);const minimum=nightRoute(s);assert.equal(s.phase,'won');assert(minimum<80);assert(s.health>minimum+20);assert.equal(s.delivered,1);});
test('flying straight at recipient fails from darkness, unlike following light pools',()=>{const s=E.create(5);E.begin(s);nightRoute(s,false);assert.equal(s.phase,'lost');assert.equal(s.reason,'dark-flight');assert.equal(s.health,0);assert(s.cargo.y>200&&s.cargo.y<260);});
test('night flight cannot inflate forever or leave controls unattended',()=>{for(const held of [true,false]){const s=E.create(5);E.begin(s);if(held)E.input(s,'down');for(let i=0;i<1000&&s.phase==='playing';i++)frame(s);assert.equal(s.phase,'lost');assert.equal(s.reason,'balloon-hit');const frozen=JSON.stringify(s);E.step(s,1);assert.equal(JSON.stringify(s),frozen);}});
test('sixth delivery real pointer/key handlers, language and retry remain independent',()=>{const h=uiHarness();h.buttons[5].onclick();assert.equal(h.ui.read().level,5);assert(h.nodes.hint.classList.values.has('hidden'));h.nodes.start.onclick();h.nodes.game.events.pointerdown({clientX:-10000,clientY:99999,pointerId:1,preventDefault(){}});assert(h.ui.read().watched);h.ui.frame(0);h.ui.frame(50);assert(h.ui.read().cargo.x>90);h.nodes.game.events.pointercancel();assert(!h.ui.read().watched);h.events.keydown({code:'Space',preventDefault(){}});assert(h.ui.read().watched);h.events.keyup({code:'Space'});assert(!h.ui.read().watched);const before=JSON.stringify(h.ui.read());h.nodes.lang.onclick();assert.equal(JSON.stringify(h.ui.read()),before);assert(h.nodes.instruction.textContent.includes('Light'));h.nodes.retry.onclick();assert.equal(h.ui.read().phase,'ready');assert.equal(h.ui.read().health,100);assert.equal(h.ui.read().time,0);assert.equal(h.ui.read().cargo.x,90);assert.equal(h.ui.read().watched,false);});
test('failure hint is optional, bilingual, nonmutating and clears on retry',()=>{const h=uiHarness();h.ui.choose(5);h.nodes.start.onclick();nightRoute(h.ui.read(),false);h.ui.renderUI();assert(!h.nodes.hint.classList.values.has('hidden'));assert(!h.nodes.status.textContent.includes('提示：'));const before=JSON.stringify(h.ui.read());h.nodes.hint.onclick();assert(h.nodes.status.textContent.includes('提示：'));assert.equal(JSON.stringify(h.ui.read()),before);h.nodes.lang.onclick();assert(h.nodes.status.textContent.includes('Hint:'));assert(h.nodes.status.textContent.includes('outside the lights'));assert.equal(JSON.stringify(h.ui.read()),before);h.nodes.retry.onclick();assert(h.nodes.hint.classList.values.has('hidden'));assert(!h.nodes.status.textContent.includes('Hint:'));});
test('sixth win reports unified progress and advances to seventh',()=>{const h=uiHarness(),calls=[];h.context.TrialProgress={complete:(...args)=>calls.push(args)};h.ui.choose(5);h.nodes.start.onclick();nightRoute(h.ui.read());h.ui.frame(0);h.ui.frame(20);assert.equal(calls.length,1);assert.equal(calls[0][1],5);h.nodes.next.onclick();assert.equal(h.ui.read().level,6);assert.equal(E.levels,7);assert.equal(h.buttons.length,7);});

test('region, navigation and canvas accessible names follow language without resetting play',()=>{const h=uiHarness();h.ui.choose(5);h.nodes.start.onclick();h.ui.frame(0);h.ui.frame(50);const before=JSON.stringify(h.ui.read());assert.equal(h.nodes['stage-region'].attributes['aria-label'],'快递操作场地');assert.equal(h.nodes['level-navigation'].attributes['aria-label'],'关卡');h.nodes.lang.onclick();assert.equal(h.nodes['stage-region'].attributes['aria-label'],'Delivery play area');assert.equal(h.nodes['level-navigation'].attributes['aria-label'],'Deliveries');assert(h.nodes.game.attributes['aria-label'].startsWith('Deliver'));assert.equal(JSON.stringify(h.ui.read()),before);h.nodes.lang.onclick();assert.equal(h.nodes['level-navigation'].attributes['aria-label'],'关卡');});
test('desktop layout allocates remaining space to canvas without clipping text or changing pointer transform',()=>{assert(html.includes('@media(min-width:900px) and (min-height:650px)'));assert(html.includes('grid-template-rows:auto auto minmax(200px,1fr) auto auto'));assert(html.includes('.stage{width:100%;height:100%;min-height:0;max-height:none;aspect-ratio:auto}'));const h=uiHarness();h.nodes.game.getBoundingClientRect=()=>({left:30,top:120,width:1068,height:410});h.nodes.start.onclick();const scale=410/520,left=30+(1068-900*scale)/2;h.nodes.game.events.pointerdown({clientX:left+100*scale,clientY:120+350*scale,pointerId:2,preventDefault(){}});assert(h.ui.read().drag);assert(Math.abs(h.ui.read().pointer.x-100)<1e-8);assert(Math.abs(h.ui.read().pointer.y-350)<1e-8);h.nodes.game.events.pointermove({clientX:left+200*scale,clientY:120+250*scale});h.ui.frame(0);h.ui.frame(50);assert(h.ui.read().cargo.x>100);});

function lanternRoute(s,route=[{x:330,y:155},{x:400,y:350},{x:650,y:350},{x:800,y:165}]){for(const p of route){E.input(s,'down',s.lantern.x,s.lantern.y-24);E.input(s,'move',p.x,p.y);for(let i=0;i<180&&s.phase==='playing'&&Math.hypot(s.lantern.x-p.x,s.lantern.y-p.y)>2;i++)frame(s);E.input(s,'release');E.input(s,'down',s.cargo.x,s.cargo.y);E.input(s,'move',p.x,p.y);for(let i=0;i<250&&s.phase==='playing'&&Math.hypot(s.cargo.x-p.x,s.cargo.y-p.y)>2;i++)frame(s);E.input(s,'release');for(let i=0;i<90&&s.phase==='playing';i++)frame(s);}}
test('optional borrowed lamp route succeeds by alternating two independently controlled objects',()=>{const s=E.create(0,true);E.begin(s);lanternRoute(s);assert.equal(s.phase,'won',JSON.stringify(s));assert(s.health>0);assert.equal(s.lights.length,3);assert.equal(E.create(1,true).lanternMode,false);});
test('moving lamp does not move plant; unlit plant fails if lamp is neglected',()=>{const s=E.create(0,true);E.begin(s);E.input(s,'down',330,131);E.input(s,'move',800,165);for(let i=0;i<180;i++)frame(s);assert.equal(s.cargo.x,100);assert.equal(s.cargo.y,350);assert(s.lantern.x>790);E.input(s,'release');E.input(s,'down',100,350);E.input(s,'move',330,155);for(let i=0;i<400&&s.phase==='playing';i++)frame(s);assert.equal(s.phase,'lost');assert.equal(s.reason,'dark');});
test('lamp and plant remain separately selectable when parked together, bounds and release hold',()=>{const s=E.create(0,true);E.begin(s);s.lantern.x=s.cargo.x;s.lantern.y=s.cargo.y;E.input(s,'down',100,326);assert.equal(s.dragKind,'lamp');E.input(s,'move',-99999,99999);for(let i=0;i<90;i++)frame(s);assert(s.lantern.x>=22&&s.lantern.y<=498);E.input(s,'release');assert.equal(s.dragKind,null);E.input(s,'down',s.cargo.x,s.cargo.y);assert.equal(s.dragKind,'plant');});
test('optional mode actual handlers preserve mode on retry, toggle only ready and translate without reset',()=>{const h=uiHarness();h.nodes.challenge.onclick();assert(h.ui.read().lanternMode);h.nodes.start.onclick();h.nodes.challenge.onclick();assert(h.ui.read().lanternMode);h.nodes.game.events.pointerdown({clientX:330,clientY:131,pointerId:4,preventDefault(){}});assert.equal(h.ui.read().dragKind,'lamp');h.nodes.game.events.pointermove({clientX:400,clientY:350});h.ui.frame(0);h.ui.frame(50);const before=JSON.stringify(h.ui.read());h.nodes.lang.onclick();assert.equal(JSON.stringify(h.ui.read()),before);assert(h.nodes.instruction.textContent.includes('gold lamp'));h.nodes.game.events.pointercancel();assert.equal(h.ui.read().dragKind,null);h.nodes.retry.onclick();assert(h.ui.read().lanternMode);assert.equal(h.ui.read().time,0);assert.equal(h.ui.read().health,100);h.nodes.challenge.onclick();assert(!h.ui.read().lanternMode);assert.equal(h.ui.read().lights.length,4);});

test('explicit pause freezes simulation, clears held input and resumes without catch-up',()=>{const h=uiHarness();h.ui.choose(5);h.nodes.start.onclick();h.nodes.watch.events.pointerdown({pointerId:1,preventDefault(){}});h.ui.frame(0);h.ui.frame(50);h.nodes.pause.onclick();assert(!h.ui.read().watched);const before=JSON.stringify(h.ui.read());h.ui.frame(500);h.ui.frame(5000);h.nodes.watch.events.pointerdown({pointerId:2,preventDefault(){}});assert.equal(JSON.stringify(h.ui.read()),before);h.nodes.lang.onclick();assert(h.nodes.status.textContent.startsWith('Paused'));h.nodes.pause.onclick();h.ui.frame(8000);assert.equal(JSON.stringify(h.ui.read()),before);h.ui.frame(8050);assert(h.ui.read().time>JSON.parse(before).time);assert(!h.ui.read().watched);});
test('hidden document pauses until explicit resume; blur alone only releases input',()=>{const h=uiHarness();h.ui.choose(1);h.nodes.start.onclick();h.ui.frame(0);h.ui.frame(50);h.events.blur();h.ui.frame(100);assert(h.ui.read().time>.05);h.context.document.hidden=true;h.events.visibilitychange();const before=JSON.stringify(h.ui.read());h.context.document.hidden=false;h.events.visibilitychange();h.ui.frame(1000);h.ui.frame(2000);assert.equal(JSON.stringify(h.ui.read()),before);h.nodes.pause.onclick();h.ui.frame(3000);h.ui.frame(3050);assert(h.ui.read().time>JSON.parse(before).time);h.nodes.retry.onclick();h.nodes.start.onclick();h.ui.frame(4000);h.ui.frame(4050);assert(h.ui.read().time>0);});

test('borrowed lamp allows a distinct southern shelf route rather than one prescribed solution',()=>{const s=E.create(0,true);E.begin(s);lanternRoute(s,[{x:100,y:470},{x:400,y:470},{x:650,y:350},{x:800,y:165}]);assert.equal(s.phase,'won',JSON.stringify(s));});

test('balloon and greenhouse instructions describe momentum before play in both languages',()=>{for(const level of [4,5]){const h=uiHarness();h.ui.choose(level);assert(h.nodes.instruction.textContent.includes('松开逐渐下降'));assert(h.nodes.instruction.textContent.includes('有惯性'));assert(!h.nodes.instruction.textContent.includes('松开就下降'));h.nodes.lang.onclick();assert(h.nodes.instruction.textContent.includes('descend gradually'));assert(h.nodes.instruction.textContent.includes('momentum'));h.nodes.start.onclick();for(let i=0;i<1000&&h.ui.read().phase==='playing';i++)frame(h.ui.read());h.ui.renderUI();assert(h.nodes.status.textContent.includes('momentum'));}});

function dragPuffer(s,x,y){E.input(s,'down',s.cargo.x,s.cargo.y);E.input(s,'move',x,y);for(let i=0;i<400&&s.phase==='playing'&&Math.hypot(s.cargo.x-x,s.cargo.y-y)>2;i++)frame(s);E.input(s,'release');}
function pufferRoute(s){dragPuffer(s,320,300);E.puff(s);dragPuffer(s,605,300);E.puff(s);dragPuffer(s,805,300);}
test('puffer delivery succeeds through slim/puffed/slim choices without speed escalation',()=>{const s=E.create(6);E.begin(s);pufferRoute(s);assert.equal(s.phase,'won',JSON.stringify(s));assert.equal(s.puffed,false);});
test('puffed parcel cannot pass narrow gate and cannot expand inside it',()=>{const s=E.create(6);E.begin(s);E.puff(s);dragPuffer(s,320,300);assert(s.cargo.x<=214.01);assert(s.blocked);E.puff(s);dragPuffer(s,264,300);assert.equal(E.puff(s),false);assert(s.sizeBlocked);assert.equal(s.cargo.r,19);});
test('slim parcel is physically swept off the route by wind',()=>{const s=E.create(6);E.begin(s);dragPuffer(s,805,300);assert.equal(s.phase,'lost');assert.equal(s.reason,'wind');assert(s.cargo.y>470);});
test('puffer actual control, language, pause and retry preserve appropriate state',()=>{const h=uiHarness();h.buttons[6].onclick();h.nodes.start.onclick();h.nodes.puff.onclick();assert(h.ui.read().puffed);h.nodes.game.events.pointerdown({clientX:110,clientY:300,pointerId:8,preventDefault(){}});h.nodes.game.events.pointermove({clientX:200,clientY:300});h.ui.frame(0);h.ui.frame(50);assert(h.ui.read().cargo.x>110);h.nodes.pause.onclick();const before=JSON.stringify(h.ui.read());h.nodes.puff.onclick();h.ui.frame(300);h.nodes.lang.onclick();assert.equal(JSON.stringify(h.ui.read()),before);assert(h.nodes.instruction.textContent.toLowerCase().includes('puff up'));assert(h.nodes.puff.textContent.includes('Puffed'));h.nodes.pause.onclick();h.nodes.retry.onclick();assert.equal(h.ui.read().time,0);assert.equal(h.ui.read().cargo.r,19);assert.equal(h.ui.read().puffed,false);assert.equal(h.ui.read().phase,'ready');});
test('seventh win reports once and borrowed lamp reports independent variant only',()=>{const h=uiHarness(),normal=[],variant=[];h.context.TrialProgress={complete:(...a)=>normal.push(a),completeVariant:(...a)=>variant.push(a)};h.ui.choose(6);h.nodes.start.onclick();pufferRoute(h.ui.read());h.ui.frame(0);h.ui.frame(50);assert.equal(normal.length,1);assert.equal(normal[0][1],6);h.nodes.next.onclick();assert.equal(h.ui.read().level,0);h.nodes.challenge.onclick();h.nodes.start.onclick();lanternRoute(h.ui.read());h.ui.frame(100);h.ui.frame(150);assert.equal(normal.length,1);assert.equal(variant.length,1);assert.equal(variant[0][1],'borrowed-lamp');assert(variant[0][2].seconds>0);});

test('puffer size changes cannot cross world edges or accept pre-start input',()=>{const s=E.create(6);assert.equal(E.puff(s),false);E.begin(s);dragPuffer(s,22,300);assert.equal(E.puff(s),false);assert.equal(s.cargo.r,19);assert(s.sizeBlocked);E.input(s,'move',NaN,Infinity);assert(Number.isFinite(s.cargo.x));});

test('all-slim upper detour remains a valid alternative to the puffed main route',()=>{const s=E.create(6);E.begin(s);for(const [x,y] of [[320,300],[320,22],[600,22],[600,300],[805,300]]){dragPuffer(s,x,y);assert.equal(s.puffed,false);assert.equal(s.cargo.r,19);}assert.equal(s.phase,'won');const direct=E.create(6);E.begin(direct);pufferRoute(direct);assert(s.time>direct.time);});
test('puffer brief allows alternative routes without revealing a specific detour',()=>{const h=uiHarness();h.ui.choose(6);assert(h.nodes.instruction.textContent.includes('也可寻找绕路'));assert(!h.nodes.instruction.textContent.includes('顶部'));h.nodes.lang.onclick();assert(h.nodes.instruction.textContent.includes('or look for a route around it'));assert(!h.nodes.instruction.textContent.includes('top'));});
